import uuid
from django.conf import settings
from django.db import models
class AttachmentScan(models.Model):
    class Status(models.TextChoices): PENDING='pending','Pending'; COMPLETED='completed','Completed'; FAILED='failed','Failed'
    id=models.UUIDField(primary_key=True,default=uuid.uuid4,editable=False); user=models.ForeignKey(settings.AUTH_USER_MODEL,on_delete=models.CASCADE,related_name='attachment_scans')
    original_filename=models.CharField(max_length=255); stored_filename=models.CharField(max_length=255,blank=True); declared_extension=models.CharField(max_length=20,blank=True); detected_extension=models.CharField(max_length=20,blank=True); declared_mime_type=models.CharField(max_length=120,blank=True); detected_mime_type=models.CharField(max_length=120,blank=True); file_size=models.PositiveIntegerField(default=0); md5_hash=models.CharField(max_length=32,blank=True); sha1_hash=models.CharField(max_length=40,blank=True); sha256_hash=models.CharField(max_length=64,blank=True)
    status=models.CharField(max_length=20,choices=Status.choices,default=Status.PENDING); risk_level=models.CharField(max_length=20,blank=True); safety_score=models.PositiveSmallIntegerField(null=True,blank=True); confidence_score=models.PositiveSmallIntegerField(null=True,blank=True); completeness_percentage=models.PositiveSmallIntegerField(null=True,blank=True); file_type_category=models.CharField(max_length=40,blank=True); extension_mismatch=models.BooleanField(default=False); double_extension_detected=models.BooleanField(default=False); executable_detected=models.BooleanField(default=False); script_detected=models.BooleanField(default=False); macro_enabled_type=models.CharField(max_length=20,blank=True); macro_detected=models.BooleanField(default=False); archive_detected=models.BooleanField(default=False); encrypted_archive=models.BooleanField(default=False)
    archive_entry_count=models.PositiveIntegerField(default=0); archive_findings=models.JSONField(default=list); pdf_findings=models.JSONField(default=dict); image_findings=models.JSONField(default=dict); office_findings=models.JSONField(default=dict); executable_findings=models.JSONField(default=dict); script_findings=models.JSONField(default=dict); apk_findings=models.JSONField(default=dict); yara_matches=models.JSONField(default=list); suspicious_strings=models.JSONField(default=list); score_breakdown=models.JSONField(default=list); positive_findings=models.JSONField(default=list); warning_findings=models.JSONField(default=list); check_results=models.JSONField(default=dict); methodology_version=models.CharField(max_length=20,blank=True); ai_security_report=models.TextField(blank=True); error_message=models.TextField(blank=True); failure_stage=models.CharField(max_length=50,blank=True); created_at=models.DateTimeField(auto_now_add=True); completed_at=models.DateTimeField(null=True,blank=True)
    class Meta: ordering=['-created_at']
